pages/blog-post:
---
blog:
    recent_posts:
        limit: 4
---
{{#partial "page"}}

{{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

<section class="page">
    <div class="ob-blog-header ob-title-banner ob-full-width-mobile
    {{#unless theme_settings.show_title_banner_gradient}} no-overlay{{/unless}}
    {{#if theme_settings.category_banner_text_only}} no-image{{/if}}">
        {{#unless theme_settings.category_banner_text_only}}
            {{#if theme_settings.blog_banner}}
                <img rel="preload" src="{{getImageManagerImageSrcset theme_settings.blog_banner}}" alt="{{blog.name}}" />
            {{else}}
                <img rel="preload" src="{{cdn (multiConcat 'assets/img/ob-custom/' theme_settings.theme_type '/blog-banner.jpg')}}" alt="{{blog.name}}" />
            {{/if}}
        {{/unless}}
        <div class="blog-header-text">
            <h1 class="page-heading">{{blog.name}}</h1>
            <div class="blog-description">
                <p>{{blog.description}}</p>
            </div>
        </div>
    </div>

    <aside class="page-sidebar ob-desktop">
        <h3 class="recent-posts">{{lang 'blog.recent_posts'}}</h3>
        {{#each blog.recent_posts}}
            {{> components/blog/sidebar-post post=this}}
        {{/each}}
    </aside>

    <div class="page-content">
        {{> components/blog/post post=blog.post show_tags=true}}
    </div>
</section>

{{/partial}}
{{> layout/base}}

components/ob-custom/global/ob-header:
{{inject 'theme_settings' theme_settings}}
{{inject 'main_settings' settings}}

<header class="header" role="banner">
    <div class="header--top">
        <div class="{{#if theme_settings.logo-position '==' 'left'}}logo-left {{else if theme_settings.logo-position '==' 'right'}}logo-right {{/if}}container">
            <a href="#" class="mobileMenu-toggle" data-mobile-menu-toggle="menu">
                <span class="mobileMenu-toggleIcon">Toggle menu</span>
            </a>

            <div class="navPages-quickSearch ob-desktop"></div>

            {{#if page_type '===' 'default'}}
                <h1 class="header-logo header-logo--{{theme_settings.logo-position}}">
                    {{> components/common/store-logo}}
                </h1>
            {{else}}
                <div class="header-logo header-logo--{{theme_settings.logo-position}}">
                    {{> components/common/store-logo}}
                </div>
            {{/if}}

            {{> components/ob-custom/global/ob-navigation}}
        </div>
    </div>
    <div class="header--bottom">
        <div class="container">
            <div class="header-promo ob-desktop ob-tablet-hidden">
                {{#if theme_settings.show_header_promo}}
                    {{> components/ob-custom/global/ob-header-promo}}
                {{/if}}
            </div>
            <div class="navPages-container" id="menu" data-menu>
                {{> components/ob-custom/global/ob-navigation-menu}}
            </div>
            <div class="header-beta-nav ob-desktop ob-tablet-hidden">
                {{#if theme_settings.show_gift_blog_links}}
                    {{#if settings.gift_certificates_enabled}}
                        <a class="beta-link gift-link"
                           href="{{urls.gift_certificate.purchase}}"
                           aria-label="{{lang 'common.gift_cert'}}"
                        >
                            {{#if theme_settings.theme_type '==' 'light'}}
                                <svg><use xlink:href="#icon-gift" /></svg>
                            {{/if}}
                            {{lang 'common.gift_cert'}}
                        </a>
                    {{/if}}
                    {{#if settings.blog_enabled}}
                        <a class="beta-link blog-link"
                           href="{{blog.url}}"
                           aria-label="{{blog.name}}"
                        >
                            {{blog.name}}
                        </a>
                    {{/if}}
                {{/if}}
            </div>
        </div>
    </div>
</header>

{{#if banners.top}}
<div class="banners" data-banner-location="top">
    {{#each (limit banners.top_metadata 1)}}
    <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-banner-id="{{this.banner-name}}">
        <div data-event-type="promotion-click">
            {{{this.content}}}
        </div>
    </div>
    {{/each}}
</div>
{{/if}}

components/ob-custom/global/ob-footer:
{{#if banners.bottom}}
    {{#if settings.data_tag_enabled}}
        <div class="banners" data-banner-location="bottom">
            {{#each (limit banners.bottom_metadata 1)}}
                <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-name="{{this.banner-name}}">
                    <div data-event-type="promotion-click">
                        {{{this.content}}}
                    </div>
                </div>
            {{/each}}
        </div>
    {{else}}
        <div class="banners" data-banner-location="bottom">
            <div class="banner">
                {{{limit banners.bottom 1}}}
            </div>
        </div>
    {{/if}}
{{/if}}

{{{region name="above_footer"}}}

<footer class="footer" role="contentinfo">
    <div class="footer-inner">
        {{#all theme_settings.is_night (if theme_settings.footer-backgroundImage '==' 'default')}}
            <img class="footer-bg ob-desktop" src="{{cdn 'assets/img/ob-custom/footer-bg-desktop.svg'}}" alt="Footer background" />
            <img class="footer-bg ob-mobile" src="{{cdn 'assets/img/ob-custom/footer-bg-mobile.svg'}}" alt="Footer background" />
        {{/all}}
        {{#all theme_settings.is_night (if theme_settings.footer-backgroundImage '==' 'custom') theme_settings.footer-backgroundImage-file}}
            <img class="footer-bg ob-desktop" src="{{getImageManagerImage theme_settings.footer-backgroundImage-file}}" alt="Footer background" />
            <img class="footer-bg ob-mobile" src="{{getImageManagerImage theme_settings.footer-backgroundImage-file-mobile}}" alt="Footer background" />
        {{/all}}
        <h2 class="footer-title-sr-only">Footer</h2>
        <div class="container">
            <div class="ob-news-section">
                {{#if theme_settings.footer_show_newsletter}}
                    <article class="footer-info-col" data-section-type="newsletterSubscription">
                        {{> components/ob-custom/global/footer/ob-subscription-form}}
                    </article>
                {{/if}}

                {{#if social_media}}
                    <article class="footer-info-col footer-info-col--small footer-social" data-section-type="footer-webPages">
                        <h3 class="footer-info-heading">{{theme_settings.footer_social_title}}</h3>
                        {{> components/common/social-links}}
                    </article>
                {{/if}}
            </div>
            <div class="ob-nav-section">
                <article class="footer-info-col footer-info-col--small" data-section-type="footer-categories">
                    <h3 class="footer-info-heading">{{theme_settings.footer_shop_title}}</h3>
                    <ul class="footer-info-list">
                        {{#each categories}}
                            <li>
                                <a href="{{url}}">{{name}}</a>
                            </li>
                        {{/each}}
                        {{#if settings.gift_certificates_enabled}}
                            <li>
                                <a href="{{urls.gift_certificate.purchase}}">
                                    {{lang 'common.gift_cert'}}
                                </a>
                            </li>
                        {{/if}}
                        {{#if theme_settings.footer_brands_link}}
                            <li>
                                <a href="/brands">View Brands</a>
                            </li>
                        {{/if}}
                    </ul>
                </article>

                {{#if theme_settings.footer_learn_column}}
                    <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                        <h3 class="footer-info-heading">{{theme_settings.footer_learn_title}}</h3>
                        <ul class="footer-info-list">
                            {{#each pages}}
                                <li>
                                    <a href="{{url}}">
                                        {{name}}
                                    </a>
                                </li>
                            {{/each}}
                        </ul>
                    </article>
                {{/if}}

                {{#if theme_settings.footer_support_column}}
                    <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                        <h3 class="footer-info-heading">{{theme_settings.footer_support_title}}</h3>
                        <ul class="footer-info-list">
                            {{> components/ob-custom/global/footer/ob-support}}
                        </ul>
                    </article>
                {{/if}}

                {{#any theme_settings.footer_show_address theme_settings.show_footer_hours}}
                    <article class="footer-info-col footer-info-col--small" data-section-type="storeInfo">
                        <h3 class="footer-info-heading">{{theme_settings.footer_address_title}}</h3>

                        {{#all settings.address theme_settings.footer_show_address}}
                            <address>{{nl2br settings.address}}</address>
                        {{/all}}

                        {{#if theme_settings.show_footer_hours}}
                            <p>{{theme_settings.store_hours}}</p>
                        {{/if}}
                    </article>
                {{/any}}
            </div>

            <div class="ob-copyright-section">
                {{#if theme_settings.show_copyright_footer}}
                    <div class="footer-copyright footer-store-date">
                        <p class="powered-by">
                            &copy; {{moment format="YYYY"}} {{settings.store_name}} | 
                            <a href="{{urls.sitemap}}">{{lang 'sitemap.page_title'}}</a> 
                        </p>
                    </div>
                {{/if}}

                {{> components/ob-custom/global/footer/ob-payment-icons}}

                {{#if theme_settings.show_copyright_footer}}
                    {{#if theme_settings.footer_obundle}}
                        <div class="footer-copyright footer-obundle">
                            <p class="designed-by">
                                Designed &amp; developed by 
                                <a href="http://www.obundle.com">
                                    oBundle
                                    <svg><use xlink:href="#icon-obundle" /></svg>
                                </a>
                            </p>
                        </div>
                    {{/if}}
                {{/if}}
            </div>
        </div>
        {{{region name="ssl_site_seal--global"}}}
    </div>
</footer>

components/common/social-links:
{{#if social_media}}
    <ul class="socialLinks socialLinks--alt">
        {{#each social_media}}
            <li class="socialLinks-item">
                <a class="icon icon--{{display_name}}" href="{{url}}" target="_blank" rel="noopener">
